lib='''def background(grid):
    """The most frequent color in the grid."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def marker_color(grid, bg=None):
    """The second most frequent color: the repeated single-cell marker color (None if there is none)."""
    from collections import Counter
    c = Counter(v for row in grid for v in row)
    if bg is None: bg = c.most_common(1)[0][0]
    rest = [v for v, _ in c.most_common() if v != bg]
    return rest[0] if rest else None

def pattern_cells(grid, bg=None, marker=None):
    """The cells (i, j, value) of the one non-background, non-marker block, in row-major order."""
    if bg is None: bg = background(grid)
    if marker is None: marker = marker_color(grid, bg)
    return [(i, j, v) for i, row in enumerate(grid) for j, v in enumerate(row)
            if v not in (bg, marker)]

def stamp_pattern(grid, bg=None, marker=None, fill=None, overwrite=True):
    """Copy the one non-background block onto every marker cell, centered on it, keeping the original block (other cells take fill)."""
    h, w = len(grid), len(grid[0])
    if bg is None: bg = background(grid)
    if marker is None: marker = marker_color(grid, bg)
    cells = pattern_cells(grid, bg, marker)
    ri, cj = cells[len(cells)//2][0], cells[len(cells)//2][1]
    offs = [(i - ri, j - cj, v) for i, j, v in cells]
    if fill is None: fill = bg
    g = [[marker if v == marker else fill for v in row] for row in grid]
    if overwrite:
        for i, j, v in cells: g[i][j] = v
    else:
        for i, row in enumerate(grid):
            for j, v in enumerate(row):
                if v not in (bg, marker): g[i][j] = v
    for i in range(h):
        for j in range(w):
            if grid[i][j] == marker:
                for di, dj, v in offs:
                    if 0 <= i + di < h and 0 <= j + dj < w: g[i + di][j + dj] = v
    return g
